    switch (value.state) {
      case "login_required":
        return t("voice.unavailable.login");
      case "subscription_required":
        return t("voice.unavailable.subscription");
      case "credits_required":
        return t("voice.unavailable.credits");
      case "billing_unavailable":
        return t("voice.unavailable.billing");
      case "local_only":
        return t("voice.unavailable.localOnly");
      case "cloud_ready":
        return "";
    }
  }

function localStatusText(value: VoiceInputStatus): string {
    const size = formatBytes(value.total_bytes);
    switch (value.local_state) {
      case "model_missing":
        return t("voice.local.modelMissing", { size });
      case "downloading":
        return t("voice.local.downloading", { percent: downloadPercent(value) });
      case "ready":
        return t("voice.local.ready");
      case "helper_missing":
        return t("voice.local.helperMissing");
      case "error":
        return t("voice.local.failed");
      case "not_checked":
        return "";
    }
  }

function microphoneError(error: unknown): string {
    const name = error instanceof DOMException ? error.name : "";
    if (name === "NotAllowedError" || name === "SecurityError") return t("voice.error.permission");
    if (name === "NotFoundError" || name === "DevicesNotFoundError") return t("voice.error.noDevice");
    return t("voice.error.capture");
  }

function encodePcm16Wav(samples: Float32Array, sampleRate: number): Uint8Array {
  const dataBytes = samples.length * 2;
  const buffer = new ArrayBuffer(44 + dataBytes);
  const view = new DataView(buffer);
  writeAscii(view, 0, "RIFF");
  view.setUint32(4, 36 + dataBytes, true);
  writeAscii(view, 8, "WAVE");
  writeAscii(view, 12, "fmt ");
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * 2, true);
  view.setUint16(32, 2, true);
  view.setUint16(34, 16, true);
  writeAscii(view, 36, "data");
  view.setUint32(40, dataBytes, true);
  for (let index = 0; index < samples.length; index += 1) {
    const value = Math.max(-1, Math.min(1, samples[index]));
    view.setInt16(44 + index * 2, value < 0 ? value * 0x8000 : value * 0x7fff, true);
  }
  return new Uint8Array(buffer);
}

function captureRuntimeErrorNotice(payload: AgentTaskEventPayload): boolean {
  if (!payload.text.trim()) return false;
  if (payload.kind === "failed") {
    const commandPresentation = formatTaskCommandErrorPresentation(payload.text);
    if (!commandPresentation) return false;
    showRuntimeErrorNotice({
      key: `${payload.task_id}:${commandPresentation.fingerprint}`,
      kind: "command",
      error: payload.text,
    });
    return true;
  }
  if (payload.kind !== "api_error") return false;
  console.error("agent task API error:", payload.text);
  const presentation = formatTaskApiError(payload.text);
  const key = `${payload.task_id}:${presentation.fingerprint}`;
  const now = Date.now();
  if ((recentRuntimeErrors.get(key) ?? 0) > now - RUNTIME_ERROR_DEDUPE_MS) return false;
  recentRuntimeErrors.set(key, now);
  for (const [seenKey, seenAt] of recentRuntimeErrors) {
    if (seenAt <= now - RUNTIME_ERROR_DEDUPE_MS) recentRuntimeErrors.delete(seenKey);
  }

  showRuntimeErrorNotice({ key, kind: "api", error: payload.text });
  return true;
}

