        ${plan.alipay_enabled ? `<button id="subscription-buy-alipay" type="button" class="${plan.wechat_enabled ? "btn-ghost" : "btn-primary"} subscription-full-button">${esc(t("subscription.alipay"))}</button>` : ""}
      </div>
