function renderCredentialSection(selected: ModelInfo | undefined): string {
    if (!selected) return "";
    if (selected.provider === "socai") return "";
    if (selected.has_key && !editingKey) return renderCredentialConfigured(selected);
    return renderHeaderKeyEntry(selected);
  }

(event) => {
        let next = index;
        if (event.key === "ArrowLeft") next = (index - 1 + tabs.length) % tabs.length;
        else if (event.key === "ArrowRight") next = (index + 1) % tabs.length;
        else if (event.key === "Home") next = 0;
        else if (event.key === "End") next = tabs.length - 1;
        else return;
        event.preventDefault();
        activate(next);
      }

(event) => {
      let width = artifactPreviewWidth;
      if (event.key === "ArrowLeft") width += 32;
      else if (event.key === "ArrowRight") width -= 32;
      else if (event.key === "Home") width = bounds().min;
      else if (event.key === "End") width = bounds().max;
      else return;
      event.preventDefault();
      applyWidth(width, true);
    }

(transcript: string): void => {
        if (replyTaskId && selectedTaskId === replyTaskId && view === "detail") {
          replyDraft = appendTranscript(replyDraft, transcript);
        } else if (!replyTaskId && view === "compose") {
          draft = appendTranscript(draft, transcript);
