    if (!type && !label) {
      // Scoped to the header's name row so verify badges elsewhere on the
      // page (e.g. recommended-user chips) can't false-positive.
      const use = $('.user-name .verify-icon use');
      const ref = use ? String(use.getAttribute('xlink:href') || use.getAttribute('href') || '') : '';
      if (use) type = /company/i.test(ref) ? 2 : 1;
    }
    const verified = type > 0 || !!label;
    if (verified && !label) {
      label = type === 2 ? '企业认证' : type === 1 ? '个人认证' : '官方认证';
    }
    return { verified, verification: label };
  }

function pendingHydration(root) {
    const preview = norm(text(root)).slice(0, 1200);
    if (/(^|\n)加载中(?:\n|$)/.test(preview)) return true;
    if (/正在加载|请稍候|loading/i.test(preview)) return true;
    return countLoadingIndicators(root) > 0;
  }

function parseCount(raw) {
    const v = String(raw || '').trim().toLowerCase().replace(/,/g, '').replace(/\+/g, '');
    const m = v.match(/(\d+(?:\.\d+)?)(万|w|k)?/);
    if (!m) return 0;
    let n = parseFloat(m[1]);
    if (m[2] === '万' || m[2] === 'w') n *= 10000;
    else if (m[2] === 'k') n *= 1000;
    return Math.round(n);
  }

function scrollFeed(opts = {}) {
    const container = findScrollableFeedContainer();
    const target = container || document.scrollingElement || document.documentElement;
    const useWindow = !container;
    const before = target.scrollTop;
    const beforeHeight = target.scrollHeight;
    const viewport = useWindow ? window.innerHeight : target.clientHeight;
    if (opts && opts.nudge_up) {
      const step = Math.max(80, Math.round(viewport / 10));
      if (useWindow) window.scrollBy({ top: -step, left: 0, behavior: 'instant' });
      else target.scrollBy({ top: -step, left: 0, behavior: 'instant' });
    } else if (useWindow) {
      window.scrollTo({ top: beforeHeight, left: 0, behavior: 'instant' });
    } else {
      target.scrollTo({ top: beforeHeight, left: 0, behavior: 'instant' });
    }
    const after = target.scrollTop;
    return {
      ok: true,
      container: useWindow ? 'window' : (container.className || container.tagName),
      before,
      after,
      moved: after !== before,
      scroll_height: beforeHeight,
      inner_height: viewport,
    };
  }

(resolve) => {
      function scrollable(el) {
        if (!(el instanceof HTMLElement)) return false;
        const style = window.getComputedStyle(el);
        const overflow = style.overflowY || style.overflow || '';
        return el.scrollHeight > el.clientHeight + 24 && ['auto', 'scroll', 'overlay'].includes(overflow);
      }
      const overlay = $('.note-detail-mask, .note-overlay, .note-detail-modal, .note-detail, #noteContainer');
      // Scope candidates to the overlay when the note is one: a page-level
      // match (e.g. a generic .scroll-container on the results feed) must
      // never win the headroom sort while a note is open.
      const candidates = [
        ...$$([
          '.note-scroller', '.note-content', '.note-detail .content', '.scroll-container',
          '.note-detail', '#noteContainer',
          '.note-detail-mask [class*="scroll"]', '.note-detail-mask [class*="content"]',
        ].join(', '), overlay || document),
        overlay,
      ].filter(Boolean);
      const seen = new Set();
      const unique = [];
      for (const node of candidates) {
        if (!(node instanceof HTMLElement) || seen.has(node)) continue;
        seen.add(node);
        unique.push(node);
      }
      unique.sort((a, b) => (b.scrollHeight - b.clientHeight) - (a.scrollHeight - a.clientHeight));
      const container = unique.find(scrollable) || null;
      if (container) {
        const before = container.scrollTop;
        container.scrollBy({ top: pixels, behavior: 'smooth' });
        setTimeout(() => {
          const after = container.scrollTop;
          resolve({
            ok: after !== before,
            container: container.className || container.id || container.tagName,
            delta: after - before,
            error: after !== before ? '' : 'scroll_did_not_move',
          });
        }, 900);
      } else if ($('section.note-item, .feeds-page .note-item, .ai-feeds-page .note-item')) {
        // Result-feed cards are mounted below the note (it's a modal): a
        // window scroll would scroll that feed, and the virtualized grid
        // then unmounts the cards a scan collected — every later card click
        // opens the wrong note (stale_note cascade). A short, unscrollable
        // note simply has nothing more to load; report instead of scrolling.
        resolve({
          ok: false,
          container: 'none',
          delta: 0,
          error: 'note_not_scrollable',
        });
      } else {
        const before = window.scrollY;
        window.scrollBy({ top: pixels, behavior: 'smooth' });
        setTimeout(() => {
          const after = window.scrollY;
          resolve({
            ok: after !== before,
            container: 'window',
            delta: after - before,
            error: after !== before ? '' : 'scroll_did_not_move',
          });
        }, 900);
      }
    }

export default async function handler(req, res) {
  setSecurityHeaders(res);

  if (req.method === 'OPTIONS') {
    res.status(204).end();
    return;
  }

  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST, OPTIONS');
    res.status(405).json({ ok: false, error: 'method_not_allowed' });
    return;
  }

  let input;
  try {
    input = await readJsonBody(req);
  } catch (error) {
    res.status(error.statusCode || 400).json({ ok: false, error: error.code || 'invalid_json' });
    return;
  }

  const events = normalizeEvents(input);
  if (events.length === 0) {
    res.status(400).json({ ok: false, error: 'no_events' });
    return;
  }
  if (events.length > MAX_EVENTS_PER_REQUEST) {
    res.status(413).json({ ok: false, error: 'too_many_events' });
    return;
  }

  const rateKey = rateLimitKey(req, events);
  if (!consumeRateLimit(rateKey, events.length)) {
    res.status(429).json({ ok: false, error: 'rate_limited' });
    return;
  }

  const sanitized = events
    .map((event) => sanitizeEvent(event))
    .filter((event) => event !== null);

  if (sanitized.length === 0) {
    res.status(400).json({ ok: false, error: 'no_valid_events' });
    return;
  }

  try {
    await forwardToAxiom(sanitized);
  } catch (error) {
    // Keep the client contract best-effort. The CLI has already handed off the
    // batch to the proxy; proxy/Axiom outages should not create retry storms or
    // leak backend details to public clients.
    console.error('telemetry forward failed', error);
  }

  res.status(202).json({ ok: true, accepted: sanitized.length });
}

function normalizeEvents(input) {
  if (Array.isArray(input)) {
    return input;
  }
  if (input && typeof input === 'object' && Array.isArray(input.events)) {
    return input.events;
  }
  if (input && typeof input === 'object') {
    return [input];
  }
  return [];
}

function sanitizeEvent(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    return null;
  }

  const flattened = flattenEvent(raw);
  const eventName = cleanString(flattened.event);
  if (!eventName || !eventName.startsWith('socai_')) {
    return null;
  }

  // No field allowlist: forward every key the client sent, sanitizing values
  // only (control chars, length caps, metadata shape). Non-scalar values other
  // than `metadata` are still dropped by sanitizeValue. Privacy is now the
  // client's responsibility — the proxy no longer gates which fields may be sent.
  const out = {};

  for (const [key, value] of Object.entries(flattened)) {
    const safe =
      key === 'metadata'
        ? sanitizeMetadata(value)
        : sanitizeValue(value, FIELD_MAX_CHARS[key] ?? MAX_STRING_CHARS);
    if (safe !== undefined) {
      out[key] = safe;
    }
  }

  // Stamp proxy_version after the loop so a client-sent value can't override it.
  out.proxy_version = 1;
  return out;
}

function sanitizeValue(value, maxChars = MAX_STRING_CHARS) {
  if (value === null) {
    return null;
  }
  switch (typeof value) {
    case 'string':
      return cleanString(value, maxChars);
    case 'number':
      return Number.isFinite(value) ? value : undefined;
    case 'boolean':
      return value;
    default:
      return undefined;
  }
}

function cleanMetadataKey(value) {
  if (typeof value !== 'string') {
    return undefined;
  }
  const key = value.trim().slice(0, MAX_METADATA_KEY_CHARS);
  if (!/^[A-Za-z0-9_.-]+$/.test(key)) {
    return undefined;
  }
  return key;
}

export default async function handler(req, res) {
  setSecurityHeaders(res);

  if (req.method === 'OPTIONS') {
    res.status(204).end();
    return;
  }

  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST, OPTIONS');
    res.status(405).json({ ok: false, error: 'method_not_allowed' });
    return;
  }

  let payload;
  try {
    payload = await readJsonBody(req);
  } catch (error) {
    res.status(error.statusCode || 400).json({ ok: false, error: error.code || 'invalid_json' });
    return;
  }

  const resourceSpans = payload && typeof payload === 'object' ? payload.resourceSpans : undefined;
  if (!Array.isArray(resourceSpans) || resourceSpans.length === 0) {
    res.status(400).json({ ok: false, error: 'no_resource_spans' });
    return;
  }
  // Same spirit as the events route's `socai_` name gate: only forward traces
  // that identify as ours.
  if (resourceAttribute(resourceSpans[0], 'service.name') !== 'socai') {
    res.status(400).json({ ok: false, error: 'unknown_service' });
    return;
  }
  if (!consumeRateLimit(rateLimitKey(req, resourceSpans))) {
    res.status(429).json({ ok: false, error: 'rate_limited' });
    return;
  }

  try {
    await forwardToAxiom({ resourceSpans });
    res.status(202).json({ ok: true });
  } catch (error) {
    // Return a retryable failure to clients. They persist trace payloads
    // locally, so an Axiom/proxy outage no longer turns a 202 into silent loss.
    console.error('trace forward failed', error);
    res.status(502).json({ ok: false, error: 'trace_forward_failed' });
  }
}

function consumeRateLimit(key) {
  const now = Date.now();
  for (const [existingKey, bucket] of rateLimits) {
    if (now - bucket.startedAt > RATE_LIMIT_WINDOW_MS * 2) {
      rateLimits.delete(existingKey);
    }
  }

  const bucket = rateLimits.get(key);
  if (!bucket || now - bucket.startedAt > RATE_LIMIT_WINDOW_MS) {
    rateLimits.set(key, { startedAt: now, count: 1 });
    return true;
  }

  bucket.count += 1;
  return bucket.count <= RATE_LIMIT_MAX_REQUESTS;
}
